using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitaryRecognitionTests
{
 static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:recognition/"+s.Revision+"/"+a),a);
 static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
 static WorldSession Ready(bool modern=true){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);var r=s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=modern?NewGameMilitary.ObservationContract:null},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);return s;}
 [Fact] public void NewObservationRecordsActualNearbyUnits(){var s=Ready();var w=s.DiagnosticSnapshot();Assert.True(NewGameMilitary.RecognitionEnabled(w));Assert.Equal(3,NewGameMilitary.KnownMilitary(w).Length);Assert.All(NewGameMilitary.KnownMilitary(w),u=>{Assert.True(u.Live);Assert.Equal(s.Seconds,u.ObservedAt);Assert.Equal("本人の目撃",u.Source);});Assert.True(NewGameMilitary.AllOwnCurrentlySeen(w));}
 [Fact] public void LegacyShapeDoesNotAcquireUnrecordedMemory(){var s=Ready(false);var w=s.DiagnosticSnapshot();Assert.Null(w.NewMilitary!.Observation);Assert.Empty(NewGameMilitary.KnownMilitary(w));Assert.DoesNotContain("ObservationPolicy",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));Assert.DoesNotContain("\"Observation\"",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));new WorldSession(ContractJson.Copy(w));}
 [Fact] public void SavedObservationRestoresSameViewAndFuture(){var s=Ready();At(s,s.Seconds+3);var w=s.DiagnosticSnapshot();var c=new WorldSession(ContractJson.Copy(w));Assert.Equal(ContractJson.CanonicalHash(NewGameMilitary.KnownMilitary(w)),ContractJson.CanonicalHash(NewGameMilitary.KnownMilitary(c.DiagnosticSnapshot())));At(s,s.Seconds+2);At(c,c.Seconds+2);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
 static WorldSession Away(){var s=Ready();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());var r=s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);Assert.All(NewGameMilitary.KnownMilitary(s.DiagnosticSnapshot()),r=>Assert.False(r.Live));return s;}
 [Fact] public void UnseenRecallMovementDoesNotUpdateRememberedPosition(){var s=Away();var c=new WorldSession(s.DiagnosticSnapshot());Send(s,NewMilitaryAction.RemoteRecall);var due=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt;At(s,due+1);At(c,due+1);var a=s.DiagnosticSnapshot();var b=c.DiagnosticSnapshot();Assert.NotEqual(NewGameMilitary.Position(a,0,s.Seconds),NewGameMilitary.Position(b,0,c.Seconds));Assert.Equal(ContractJson.CanonicalHash(NewGameMilitary.KnownMilitary(a)),ContractJson.CanonicalHash(NewGameMilitary.KnownMilitary(b)));Assert.False(NewGameMilitary.AllOwnCurrentlySeen(a));Assert.All(NewGameMilitary.KnownMilitary(a),r=>Assert.Equal(r.Position,r.Next));new WorldSession(a);}
 [Fact] public void ExistingSaveCanStartObservationWithoutInventingPast(){var s=Ready(false);long before=s.Seconds;At(s,before+2);var i=Input(s,NewMilitaryAction.ObserveField) with{ObservationPolicy=NewGameMilitary.ObservationContract};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();Assert.Single(w.NewMilitary!.Observation!.Frames);Assert.All(NewGameMilitary.KnownMilitary(w),r=>Assert.Equal(s.Seconds,r.ObservedAt));new WorldSession(w);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.Observation!.Frames);}
 [Theory][InlineData(0)][InlineData(1)] public void UnknownOrMisplacedObservationPolicyIsAtomic(int kind){var s=Ready(false);var i=Input(s,kind==0?NewMilitaryAction.ObserveField:NewMilitaryAction.Hold) with{ObservationPolicy=kind==0?"unknown":NewGameMilitary.ObservationContract};string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void ForgedOrMissingSavedObservationIsRejected(int kind){var s=Ready();At(s,s.Seconds+2);var w=s.DiagnosticSnapshot();var o=w.NewMilitary!.Observation!;if(kind==0)o=o with{Observer=ContractFixture.Lord};else if(kind==1){var f=o.Frames[0];var u=f.Units[0];o.Frames[0]=f with{Units=[u with{Position=new(u.Position.X+1000,u.Position.Y)},..f.Units.Skip(1)]};}else if(kind==2)o=o with{Frames=o.Frames.Skip(1).ToArray()};else if(kind==3)o=o with{Frames=o.Frames.Append(o.Frames[^1]).ToArray()};else if(kind==4)o=o with{Contract="unknown"};else o=o with{Frames=o.Frames.Where(f=>f.At!=s.Seconds-1).ToArray()};w.NewMilitary=w.NewMilitary with{Observation=o};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void VisibleFrameHeadingStillAllowsImmediateLocalActions(){var s=Ready();Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Hold),s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Report);new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void UnseenCouriersHaveNoProjectedPositionOrPurpose(){var s=Away();Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();At(s,d.DueAt-1);var w=s.DiagnosticSnapshot();Assert.NotEmpty(NewGameMilitary.CourierFrames(w,s.Seconds));Assert.Empty(NewGameMilitary.ProjectNearbyMilitaryCouriers(w));}
 [Fact]public void RangeIncludesExactlyEightyMetersAndThenKeepsLastPosition(){var s=Ready();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());void Form(long length){var r=s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=a,B=new(a.X+length,a.Y)},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);}Form(80000);var exact=NewGameMilitary.KnownMilitary(s.DiagnosticSnapshot()).Single(r=>r.Unit==NewGameMilitary.UnitIds[2]);Assert.True(exact.Live);Assert.Equal(80000,RegionalGround.Distance(a,exact.Position));Form(82000);var past=NewGameMilitary.KnownMilitary(s.DiagnosticSnapshot()).Single(r=>r.Unit==exact.Unit);Assert.False(past.Live);Assert.Equal(exact.Position,past.Position);Assert.Equal(past.Position,past.Next);new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void RemoteAnswerCreationIsNotKnowledgeAndOnlyMainUnitGetsReply(){var s=Away();var before=NewGameMilitary.KnownMilitary(s.DiagnosticSnapshot());Send(s,NewMilitaryAction.InquireUnitKnown);var d=s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();At(s,d.DueAt);var receipt=s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last();Assert.Equal(ContractJson.CanonicalHash(before),ContractJson.CanonicalHash(NewGameMilitary.KnownMilitary(s.DiagnosticSnapshot())));Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,receipt.ReplyMessage,s.PlayerControl.Value));At(s,receipt.ReplyDueAt);var rows=NewGameMilitary.KnownMilitary(s.DiagnosticSnapshot());var main=rows.Single(r=>r.Unit==NewGameMilitary.UnitIds[0]);Assert.False(main.Live);Assert.Equal("受領した本隊の返書",main.Source);Assert.Equal(receipt.At,main.ObservedAt);Assert.Null(main.Morale);foreach(var wing in rows.Where(r=>r.Unit!=main.Unit))Assert.Equal(before.Single(r=>r.Unit==wing.Unit),wing);new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void NewDirectObservationWinsOverOldReceivedReply(){var s=Away();Send(s,NewMilitaryAction.InquireUnitKnown);var d=s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();At(s,d.DueAt);Send(s,NewMilitaryAction.RemoteRecall);var order=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();At(s,order.DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);var rows=NewGameMilitary.KnownMilitary(s.DiagnosticSnapshot());Assert.All(rows,r=>{Assert.True(r.Live);Assert.Equal("本人の目撃",r.Source);});new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void UnseenFlankCannotEnablePreciseReportOrDirectFormation(){var s=Ready();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=a,B=new(a.X+110000,a.Y)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Assert.False(NewGameMilitary.AllOwnCurrentlySeen(s.DiagnosticSnapshot()));foreach(var action in new[]{NewMilitaryAction.Hold,NewMilitaryAction.Report}){string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,action),s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}Send(s,NewMilitaryAction.Recall);}
 [Fact]public void ObservationForkMatchesDeepIsolationAndNeverMutatesOriginal(){var s=Away();Send(s,NewMilitaryAction.InquireUnitKnown);var d=s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();At(s,d.DueAt);var w=s.DiagnosticSnapshot();string original=ContractJson.CanonicalHash(w);var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static;var before=typeof(NewGameMilitary).GetMethod("BeforeState",flags)!;var samples=typeof(NewGameMilitary).GetMethod("DirectMilitarySamples",flags)!;foreach(var frame in w.NewMilitary!.Observation!.Frames){var deep=(ContractWorld)before.Invoke(null,[w,frame.At,frame.Revision,false])!;var fork=(ContractWorld)before.Invoke(null,[w,frame.At,frame.Revision,true])!;Assert.Equal(ContractJson.CanonicalHash(samples.Invoke(null,[deep])),ContractJson.CanonicalHash(samples.Invoke(null,[fork])));}ContractValidation.Validate(w);Assert.Equal(original,ContractJson.CanonicalHash(w));}
}
